// GetManyByIDs retrieves multiple Step records by their IDs in a single query
func (r *StepRepository) GetManyByIDs(ctx context.Context, ids []types.IdentityUUID) (map[types.IdentityUUID]*types.Step, error) {
	if len(ids) == 0 {
		return map[types.IdentityUUID]*types.Step{}, nil
	}

	// Dedupe IDs
	seen := make(map[types.IdentityUUID]bool)
	uniqueIDs := make([]types.IdentityUUID, 0, len(ids))
	for _, id := range ids {
		if !seen[id] {
			seen[id] = true
			uniqueIDs = append(uniqueIDs, id)
		}
	}

	// Build WHERE id IN (...) clause
	placeholders := make([]string, len(uniqueIDs))
	args := make([]interface{}, len(uniqueIDs))
	for i, id := range uniqueIDs {
		placeholders[i] = fmt.Sprintf("$%d", i+1)
		args[i] = id.ToUUID()
	}

	// Build query with explicit column order
	query := fmt.Sprintf(`SELECT "id", "recipe_id", "position", "instruction", "timings", "scratch", "created_at", "created_by", "updated_at", "updated_by", "entity_key", "ref_id", "deleted_on_ref", "_version" FROM step WHERE id IN (%s)`, strings.Join(placeholders, ", "))

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results into map
	resultMap := make(map[types.IdentityUUID]*types.Step, len(uniqueIDs))
	for rows.Next() {
		entity := &types.Step{}

		// Create temporary variables for nullable fields that need pointer scanning

		var tempTimings []byte
		var tempScratch sql.NullString

		// Create temporary variables for relationship foreign keys (we don't store these in the struct)
		var tempRelRecipe *types.IdentityUUID
		var tempRelRef *types.IdentityUUID

		// Scan all fields in schema order (matches DDL column order)
		err := rows.Scan(

			&entity.Id,

			&tempRelRecipe,

			&entity.Position,

			&entity.Instruction,

			&tempTimings,

			&tempScratch,

			&entity.CreatedAt,

			&entity.CreatedBy,

			&entity.UpdatedAt,

			&entity.UpdatedBy,

			&entity.EntityKey,

			&tempRelRef,

			&entity.DeletedOnRef,

			&entity.Version,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present

		if len(tempTimings) > 0 {
			if err := unmarshalGenericJSONFieldValue(tempTimings, &entity.Timings); err != nil {
				return nil, fmt.Errorf("failed to decode JSON field timings: %w", err)
			}
		}
		if tempScratch.Valid {
			entity.Scratch = tempScratch.String
		}

		// Set relationship IDs from scanned FK values
		if tempRelRecipe != nil {
			entity.Recipe.Id = stepUUIDPtr(*tempRelRecipe)
		}
		if tempRelRef != nil {
			entity.Ref.Id = stepUUIDPtr(*tempRelRef)
		}

		entityID, ok := stepUUIDValue(entity.Id)
		if !ok {
			continue
		}
		resultMap[entityID] = entity
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating rows: %w", err)
	}

	return resultMap, nil
}

